sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float2 center;
uniform float style;
uniform float alpha;

half4 main(float2 coord) {
    float theta = radians(angle);
    float2 d = float2(cos(theta), sin(theta));
    float2 normal = float2(-sin(theta), cos(theta));
    float2 c = center * size;
    float2 v = coord - c;
    if (style > 0.5) {
        half4 copy = image.eval(c + reflect(v, normal)) * half(clamp(alpha, 0.0, 1.0));
        return copy + image.eval(coord) * (1.0 - copy.a);
    }
    float side = dot(v, normal);
    float2 sc = coord;
    if (side < 0.0) {
        sc = c + reflect(v, normal);
    }
    return image.eval(sc);
}
